bash -lc 'cat > /app/extract_m486.py << "PY"
#!/usr/bin/env python3
import sys, re, json

def extract_texts(path):
    texts = []
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                if line.startswith("M486"):
                    m = re.match(r"M486\s+A(.+)$", line)
                    if m:
                        t = m.group(1).strip()
                        if t:
                            texts.append(t)
    except FileNotFoundError:
        pass
    return texts

def main():
    path = sys.argv[1] if len(sys.argv) > 1 else '/app/text.gcode'
    texts = extract_texts(path)
    print(json.dumps(texts, ensure_ascii=False, indent=2))

if __name__ == '__main__':
    main()
PY' && python3 /app/extract_m486.py /app/text.gcode'

